"""Command-line interface: `gen` and `show` subcommands."""

import argparse
import json
import os
import re
import sys
from typing import List, Optional

from . import audit as audit_mod
from . import keybundle
from . import operations as operations_mod
from . import restore as restore_mod
from . import tenantbundle
from .audit import AuditLog, InvalidCursor, LedgerError
from .crypto import SUPPORTED_ALGORITHMS
from .operations import OperationStore
from .policy import PolicyError, PolicyStore, validate_rules
from .provider import ProviderInvalidMaterial, ProviderUnavailable
from .server import _resolve_committed_operation, serve
from .store import IMPORT_CONFLICT, KeyStore, LockTimeout, is_valid_key_id

DEFAULT_DATA_DIR = os.environ.get("KEYMGR_DATA_DIR", "keymgr_data")


def _positive_int(value: str) -> int:
    """argparse type: a positive integer version (ASCII digits only)."""
    if not re.fullmatch(r"[0-9]+", value):
        raise argparse.ArgumentTypeError(
            "field version must be a positive integer"
        )
    ivalue = int(value)
    if ivalue < 1:
        raise argparse.ArgumentTypeError(
            "field version must be a positive integer"
        )
    return ivalue


def build_parser() -> argparse.ArgumentParser:
    """Construct the CLI argument parser."""
    parser = argparse.ArgumentParser(
        prog="keymgr", description="Multi-tenant key management backend."
    )
    parser.add_argument(
        "--data-dir", default=DEFAULT_DATA_DIR,
        help="directory for key material (default: %(default)s)",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    def tenant_parser(name, **kwargs):
        p = sub.add_parser(name, **kwargs)
        p.add_argument("--tenant-id", required=True)
        p.add_argument(
            "--operator", required=True,
            help="non-empty X-Operator-Id of the caller",
        )
        return p

    p_gen = tenant_parser("gen", help="generate a new key")
    p_gen.add_argument("--algorithm", required=True,
                       help="one of: %s" % ", ".join(SUPPORTED_ALGORITHMS))
    p_gen.add_argument("--label", required=True)

    p_show = tenant_parser("show", help="show an existing key")
    p_show.add_argument("--key-id", required=True)

    p_rotate = tenant_parser("rotate", help="rotate a key to a new version")
    p_rotate.add_argument("--key-id", required=True)
    p_rotate.add_argument("--algorithm", required=True,
                          help="one of: %s" % ", ".join(SUPPORTED_ALGORITHMS))
    p_rotate.add_argument(
        "--idempotency-key", required=True,
        help="1-128 chars A-Za-z0-9._~- ; retries reuse the result",
    )

    p_version = tenant_parser("version", help="show a specific key version")
    p_version.add_argument("--key-id", required=True)
    p_version.add_argument("--version", required=True, type=_positive_int)

    p_current = tenant_parser("current", help="show the current key version")
    p_current.add_argument("--key-id", required=True)

    p_revoke = tenant_parser("revoke", help="revoke a key")
    p_revoke.add_argument("--key-id", required=True)
    p_revoke.add_argument("--reason", required=True)

    p_status = tenant_parser("status", help="show a key's revocation status")
    p_status.add_argument("--key-id", required=True)

    p_export = tenant_parser("export", help="export a key as an encrypted bundle")
    p_export.add_argument("--key-id", required=True)
    p_export.add_argument("--passphrase", required=True)

    p_import = tenant_parser("import", help="import a key from an encrypted bundle")
    p_import.add_argument("--passphrase", required=True)
    p_import.add_argument("--bundle", required=True)
    p_import.add_argument(
        "--idempotency-key", required=True,
        help="1-128 chars A-Za-z0-9._~- ; retries reuse the result",
    )

    p_backup = tenant_parser(
        "backup", help="back up all of a tenant's keys and policy"
    )
    p_backup.add_argument("--passphrase", required=True)

    p_restore = tenant_parser(
        "restore", help="restore a tenant from an encrypted backup bundle"
    )
    p_restore.add_argument("--passphrase", required=True)
    p_restore.add_argument("--bundle", required=True)
    p_restore.add_argument(
        "--idempotency-key", required=True,
        help="1-128 chars A-Za-z0-9._~- ; retries reuse the result",
    )

    p_operation = tenant_parser(
        "operation", help="show one idempotent operation's status"
    )
    p_operation.add_argument(
        "--operation-id", required=True,
        help="UUID4 operation_id returned by rotate/import/restore",
    )

    p_audit = tenant_parser("audit", help="list a tenant's audit events")
    p_audit.add_argument("--key-id", default=None,
                         help="filter to one key_id (must be a UUID4)")
    p_audit.add_argument("--action", default=None,
                         help="one of: %s" % ", ".join(audit_mod.ACTIONS))
    p_audit.add_argument("--limit", type=int, default=100,
                         help="page size, 1-1000 (default: %(default)s)")
    p_audit.add_argument("--cursor", default=None,
                         help="pagination cursor from a previous response")

    p_policy = sub.add_parser("policy", help="manage a tenant's action policy")
    p_policy.add_argument(
        "--operator", required=True,
        help="non-empty X-Operator-Id of the caller",
    )
    policy_sub = p_policy.add_subparsers(
        dest="policy_command", required=True
    )
    p_policy_show = policy_sub.add_parser(
        "show", help="show a tenant's policy"
    )
    p_policy_show.add_argument("--tenant-id", required=True)
    p_policy_set = policy_sub.add_parser(
        "set", help="replace a tenant's policy"
    )
    p_policy_set.add_argument("--tenant-id", required=True)
    p_policy_set.add_argument(
        "--rules", required=True,
        help='JSON array of {"subject","actions","effect"} rules',
    )
    p_policy_delete = policy_sub.add_parser(
        "delete", help="delete a tenant's policy"
    )
    p_policy_delete.add_argument("--tenant-id", required=True)

    p_serve = sub.add_parser("serve", help="run the HTTP server")
    p_serve.add_argument("--host", default="127.0.0.1")
    p_serve.add_argument("--port", type=int, default=8080)

    return parser


def _print(obj: dict) -> None:
    """Print a single-line JSON object."""
    print(json.dumps(obj, separators=(",", ":")))


def _fail(message: str, exit_code: int) -> int:
    print(json.dumps({"error": message}, separators=(",", ":")),
          file=sys.stderr)
    return exit_code


def _ledger_fail(exc: Exception) -> int:
    return _fail("audit ledger failure: %s" % exc, 1)


def _attempt(store, tenant_id, key_id, action, outcome) -> bool:
    """Record one attempt; False means a ledger failure was reported."""
    try:
        store.audit_attempt(tenant_id, key_id, action, outcome)
    except LedgerError as exc:
        _ledger_fail(exc)
        return False
    return True


def _conflict(store) -> bool:
    """Record an invisible tenant_conflict; False on ledger failure."""
    try:
        store.audit_conflict()
    except LedgerError as exc:
        _ledger_fail(exc)
        return False
    return True


def _identifiers_ok(tenant_id, key_id) -> bool:
    """Whether both identifiers are usable for a tenant-visible event."""
    return bool(tenant_id) and (key_id is None or is_valid_key_id(key_id))


def _deny(store, tenant_id, key_id, action) -> int:
    """Audit and report a policy rejection (HTTP 403 -> exit code 3)."""
    if not _identifiers_ok(tenant_id, key_id):
        if not _conflict(store):
            return 1
    elif not _attempt(store, tenant_id, key_id, action,
                      audit_mod.OUTCOME_REJECTED):
        return 1
    return _fail("action not permitted by policy", 3)


def _http_to_cli(http_status: int) -> int:
    return {201: 0, 200: 0, 400: 2, 403: 3, 409: 3, 404: 4}.get(
        http_status, 1
    )


def _terminal_rejection(
    op_store, store, operation, tenant_id, key_id, action,
    http_status, message,
):
    """Durably persist a bound op's terminal rejection and append it.

    CLI counterpart of the HTTP handler: the operation kind, the exact key_id
    rule, the terminal status, the complete error response and the audit
    descriptor are merged into the durable context *before* the one rejected
    event (named after the operation_id, deduped on event_id) is appended, so a
    crash and startup recovery replay this exact 403/404/409 verbatim instead
    of re-evaluating the policy or re-reading the object. Returns
    ``(http_status, body)`` for idempotent_run.
    """
    op_id = operation.operation_id
    body = {"error": message, "operation_id": op_id}
    kind = (operation.details or {}).get("kind")
    audit_key_id = (
        None if kind == "restore"
        else (key_id if is_valid_key_id(key_id) else None)
    )
    op_store.stage_terminal(
        operation,
        http_status,
        body,
        audit={
            "action": action,
            "outcome": audit_mod.OUTCOME_REJECTED,
            "tenant_id": tenant_id,
            "key_id": audit_key_id,
        },
    )
    store.audit_attempt(
        tenant_id, audit_key_id, action, audit_mod.OUTCOME_REJECTED,
        event_id=op_id,
    )
    return http_status, body


def _provider_terminal(
    op_store, store, operation, http_status, message
):
    """Persist a bound op's provider-failure terminal and append it.

    CLI counterpart of the HTTP handler: after the Idempotency-Key is bound,
    a KMS/HSM load/contract/call/handle-delete failure (503) or a refusal of
    imported material (400) is a durable terminal -- the safe response is
    staged, one rejected event named after the operation_id is appended
    (rotate projects the request key_id, import the in-bundle key_id, restore
    null), and the op is finished, so an HTTP/CLI cross-retry replays exactly
    this result and the event is never duplicated. Raises OSError/LedgerError
    if that persistence itself fails (the caller finalizes failed(500)).
    """
    op_id = operation.operation_id
    body = {"error": message, "operation_id": op_id}
    details = operation.details or {}
    kind = details.get("kind")
    action = (
        audit_mod.ACTION_ROTATE
        if kind == "rotate"
        else audit_mod.ACTION_IMPORT
    )
    audit_key_id = (
        None if kind == "restore"
        else (
            details.get("key_id")
            if is_valid_key_id(details.get("key_id"))
            else None
        )
    )
    op_store.stage_terminal(
        operation,
        http_status,
        body,
        audit={
            "action": action,
            "outcome": audit_mod.OUTCOME_REJECTED,
            "tenant_id": operation.tenant_id,
            "key_id": audit_key_id,
        },
    )
    store.audit_attempt(
        operation.tenant_id, audit_key_id, action,
        audit_mod.OUTCOME_REJECTED, event_id=op_id,
    )
    op_store.finish(operation, operations_mod.STATUS_FAILED, http_status, body)
    return http_status, body


def _idem_key_error(key) -> bool:
    """Validate an --idempotency-key; report exit 2 when malformed."""
    if not operations_mod.is_valid_idempotency_key(key):
        _fail(
            "field idempotency_key must be 1-128 characters from "
            "A-Za-z0-9._~-", 2
        )
        return True
    return False


def _emit_operation_result(http_status: int, body: dict) -> int:
    """Print a terminal operation's body and return the CLI exit code."""
    if 200 <= http_status < 300:
        _print(body)
    else:
        # Errors contain only error and operation_id.
        print(
            json.dumps(
                {
                    "error": body.get("error", "request failed"),
                    "operation_id": body.get("operation_id"),
                },
                separators=(",", ":"),
            ),
            file=sys.stderr,
        )
    return _http_to_cli(http_status)


def _idem_serve_existing(op_store, kind, record) -> "Optional[int]":
    """Replay/conflict/wait for a bound key; None means the key is unbound."""
    if kind == "new":
        return None
    if kind == "conflict":
        return _emit_operation_result(
            409,
            {
                "error": "Idempotency-Key is already bound to a different "
                "request",
                "operation_id": record.operation_id,
            },
        )
    if not record.is_terminal():
        record = op_store.await_terminal(record)
    if record.is_terminal():
        return _emit_operation_result(record.http_status, record.response)
    # Waiter outlived the 5 s budget: timed_out without mutating the owner.
    return _emit_operation_result(
        503,
        {
            "error": "operation timed out waiting for a lock",
            "operation_id": record.operation_id,
        },
    )


def idempotent_run(op_store, store, path, tenant_id, operator, body, key,
                   validator, executor, decoder=None):
    """CLI counterpart of the HTTP idempotency guard.

    Returns a process exit code. ``validator()`` runs cheap side-effect-free
    request checks *before* the binding lookup and returns None on success or
    an ``(exit_code, message)`` refusal (a refusal is never audited and never
    consumes the key). ``decoder`` (when given) performs the side-effect-free
    but expensive validation -- bundle decryption -- *after* an already-bound
    key has been replayed/conflicted but *before* a new key is bound, so a
    wrong passphrase neither masks a replay nor consumes the key.
    ``executor(operation) -> (http_status, body)`` runs once for a new binding
    and may raise ProviderInvalidMaterial / ProviderUnavailable /
    LedgerError / LockTimeout.
    """
    if _idem_key_error(key):
        return 2
    normalized = operations_mod.normalize_body(body)

    refusal = validator()
    if refusal is not None:
        code, message = refusal
        return _fail(message, code)

    # An already-bound key replays/conflicts before the expensive decoder
    # (bundle decryption), so a bad passphrase on a retry never masks a
    # replay or consumes the key.
    peek = op_store.peek(tenant_id, operator, path, normalized, key)
    existing = _idem_serve_existing(op_store, peek.kind, peek.record)
    if existing is not None:
        return existing

    if decoder is not None:
        refusal = decoder()
        if refusal is not None:
            code, message = refusal
            return _fail(message, code)

    # begin() is authoritative for the bind (another process may have won
    # between the peek and here).
    begin = op_store.begin(tenant_id, operator, path, normalized, key)
    existing = _idem_serve_existing(op_store, begin.kind, begin.record)
    if existing is not None:
        return existing

    operation = begin.record
    op_id = operation.operation_id
    try:
        http_status, resp = executor(operation)
    except LockTimeout:
        body_err = {
            "error": "operation timed out waiting for a lock",
            "operation_id": op_id,
        }
        op_store.finish(
            operation, operations_mod.STATUS_TIMED_OUT, 503, body_err
        )
        return _emit_operation_result(503, body_err)
    except ProviderInvalidMaterial as exc:
        try:
            http_status, body_err = _provider_terminal(
                op_store, store, operation, 400, str(exc)
            )
            return _emit_operation_result(http_status, body_err)
        except (OSError, LedgerError) as persist_exc:
            body_err = {
                "error": "audit ledger failure: %s" % persist_exc,
                "operation_id": op_id,
            }
            op_store.finish(
                operation, operations_mod.STATUS_FAILED, 500, body_err
            )
            return _emit_operation_result(500, body_err)
    except ProviderUnavailable:
        try:
            http_status, body_err = _provider_terminal(
                op_store, store, operation, 503,
                "key management provider is unavailable",
            )
            return _emit_operation_result(http_status, body_err)
        except (OSError, LedgerError) as persist_exc:
            body_err = {
                "error": "audit ledger failure: %s" % persist_exc,
                "operation_id": op_id,
            }
            op_store.finish(
                operation, operations_mod.STATUS_FAILED, 500, body_err
            )
            return _emit_operation_result(500, body_err)
    except OSError as exc:
        # A pre-commit staging/write failure happened before the commit-point
        # append: file and handles were rolled back, nothing committed.
        # Finalize failed(500).
        body_err = {
            "error": "audit ledger failure: %s" % exc,
            "operation_id": op_id,
        }
        op_store.finish(operation, operations_mod.STATUS_FAILED, 500, body_err)
        return _emit_operation_result(500, body_err)
    except LedgerError as exc:
        body_err = {
            "error": "audit ledger failure: %s" % exc,
            "operation_id": op_id,
        }
        op_store.finish(operation, operations_mod.STATUS_FAILED, 500, body_err)
        return _emit_operation_result(500, body_err)
    resp = dict(resp)
    resp["operation_id"] = op_id
    state = operations_mod.state_for_http_status(http_status)
    op_store.finish(operation, state, http_status, resp)
    return _emit_operation_result(http_status, resp)


def main(argv: Optional[List[str]] = None) -> int:
    """CLI entry point; returns a process exit code.

    A KMS/HSM backend failure maps to exit code 1 (HTTP 503) with a generic
    message; malformed imported material maps to exit code 2 (HTTP 400).
    """
    try:
        return _run(argv)
    except ProviderInvalidMaterial as exc:
        return _fail(str(exc), 2)
    except ProviderUnavailable:
        # Generic wording: never print a handle or material in the error.
        return _fail("key management provider is unavailable", 1)


def _run(argv: Optional[List[str]] = None) -> int:
    """Parse and execute one CLI command."""
    args = build_parser().parse_args(argv)

    if args.command == "serve":
        serve(args.host, args.port, args.data_dir)
        return 0

    audit_log = AuditLog(args.data_dir)
    store = KeyStore(args.data_dir, audit_log)
    policies = PolicyStore(args.data_dir, audit_log)
    coordinator = restore_mod.RestoreCoordinator(store, policies)
    # Resolve any operations left pending by a crashed CLI/server run, after
    # the key/restore outbox recovery above has settled the mutation.
    op_store = OperationStore(args.data_dir, audit_log)
    op_store.recover_pending(
        lambda record, event: _resolve_committed_operation(
            store, policies, record, event
        )
    )

    if not getattr(args, "operator", None):
        return _fail(
            "field operator must be a non-empty string", 2
        )

    def allowed(action, key_id=None) -> bool:
        """Policy gate; on denial the response/audit was already handled."""
        if policies.is_allowed(args.tenant_id, action, args.operator):
            return True
        return False  # caller returns _deny(...)

    if args.command == "gen":
        if not args.tenant_id or args.algorithm not in SUPPORTED_ALGORITHMS:
            if not _identifiers_ok(args.tenant_id, None):
                if not _conflict(store):
                    return 1
            elif not _attempt(
                store, args.tenant_id, None,
                audit_mod.ACTION_CREATE, audit_mod.OUTCOME_REJECTED,
            ):
                return 1
            if not args.tenant_id:
                return _fail("field tenant_id must be a non-empty string", 2)
            return _fail(
                "unsupported value for field algorithm: %r (supported: %s)"
                % (args.algorithm, ", ".join(SUPPORTED_ALGORITHMS)),
                2,
            )
        if not allowed(audit_mod.ACTION_CREATE):
            return _deny(store, args.tenant_id, None, audit_mod.ACTION_CREATE)
        try:
            record = store.create(args.tenant_id, args.algorithm, args.label)
        except LedgerError as exc:
            return _ledger_fail(exc)
        _print(record.to_create_response())
        return 0

    if args.command in ("show", "current"):
        if not is_valid_key_id(args.key_id):
            if not _identifiers_ok(args.tenant_id, args.key_id):
                if not _conflict(store):
                    return 1
            return _fail("field key_id must be a UUID4", 2)
        if not allowed(audit_mod.ACTION_READ):
            return _deny(store, args.tenant_id, args.key_id,
                         audit_mod.ACTION_READ)
        record = store.get(args.key_id, args.tenant_id)
        if record is None:
            if not _attempt(
                store, args.tenant_id, args.key_id,
                audit_mod.ACTION_READ, audit_mod.OUTCOME_REJECTED,
            ):
                return 1
            return _fail("key not found", 4)
        if not _attempt(
            store, args.tenant_id, args.key_id,
            audit_mod.ACTION_READ, audit_mod.OUTCOME_SUCCESS,
        ):
            return 1
        if args.command == "show":
            _print(record.to_get_response())
        else:
            _print(record.current.to_version_response(args.key_id))
        return 0

    if args.command == "rotate":
        # The Idempotency-Key is validated before any other parameter (and
        # before the binding/execution): a malformed key is an exit-2 error
        # with no audit event, operation record, key change or provider
        # handle -- exactly like the HTTP endpoint.
        if _idem_key_error(args.idempotency_key):
            return 2
        if not args.tenant_id:
            return _fail("field tenant_id must be a non-empty string", 2)
        if not is_valid_key_id(args.key_id):
            return _fail("field key_id must be a UUID4", 2)
        if args.algorithm not in SUPPORTED_ALGORITHMS:
            return _fail(
                "unsupported value for field algorithm: %r (supported: %s)"
                % (args.algorithm, ", ".join(SUPPORTED_ALGORITHMS)),
                2,
            )

        body = {
            "tenant_id": args.tenant_id,
            "algorithm": args.algorithm,
        }
        path = "/v1/keys/%s/rotate" % args.key_id

        def execute(operation):
            # Kind/exact key_id are durable before the authorization check so
            # a 403 terminal replays from context alone after a crash.
            op_store.update_details(
                operation,
                {"kind": "rotate", "key_id": args.key_id,
                 "algorithm": args.algorithm},
            )
            if not policies.is_allowed(
                args.tenant_id, audit_mod.ACTION_ROTATE, args.operator
            ):
                return _terminal_rejection(
                    op_store, store, operation,
                    args.tenant_id, args.key_id,
                    audit_mod.ACTION_ROTATE, 403,
                    "action not permitted by policy",
                )

            def stage_success(committed_record):
                body = committed_record.to_rotate_response()
                body["operation_id"] = operation.operation_id
                op_store.stage_terminal(operation, 201, body)

            record = store.rotate(
                args.key_id, args.tenant_id, args.algorithm,
                event_id=operation.operation_id,
                lock_timeout=operations_mod.LOCK_WAIT_SECONDS,
                pre_commit=stage_success,
            )
            if record is None:
                return _terminal_rejection(
                    op_store, store, operation,
                    args.tenant_id, args.key_id,
                    audit_mod.ACTION_ROTATE, 404, "key not found",
                )
            return 201, record.to_rotate_response()

        return idempotent_run(
            op_store, store, path, args.tenant_id, args.operator, body,
            args.idempotency_key, lambda: None, execute,
        )

    if args.command == "version":
        if not is_valid_key_id(args.key_id):
            if not _identifiers_ok(args.tenant_id, args.key_id):
                if not _conflict(store):
                    return 1
            return _fail("field key_id must be a UUID4", 2)
        if not allowed(audit_mod.ACTION_READ):
            return _deny(store, args.tenant_id, args.key_id,
                         audit_mod.ACTION_READ)
        result = store.get_version(
            args.key_id, args.tenant_id, args.version
        )
        if result is None:
            if not _attempt(
                store, args.tenant_id, args.key_id,
                audit_mod.ACTION_READ, audit_mod.OUTCOME_REJECTED,
            ):
                return 1
            return _fail("version not found", 4)
        if not _attempt(
            store, args.tenant_id, args.key_id,
            audit_mod.ACTION_READ, audit_mod.OUTCOME_SUCCESS,
        ):
            return 1
        _record, ver = result
        _print(ver.to_version_response(args.key_id))
        return 0

    if args.command == "revoke":
        if not args.tenant_id or not args.reason:
            if not _identifiers_ok(args.tenant_id, args.key_id):
                if not _conflict(store):
                    return 1
            elif not _attempt(
                store, args.tenant_id, args.key_id,
                audit_mod.ACTION_REVOKE, audit_mod.OUTCOME_REJECTED,
            ):
                return 1
            if not args.tenant_id:
                return _fail("field tenant_id must be a non-empty string", 2)
            return _fail("field reason must be a non-empty string", 2)
        if not is_valid_key_id(args.key_id):
            if not _conflict(store):
                return 1
            return _fail("field key_id must be a UUID4", 2)
        if not allowed(audit_mod.ACTION_REVOKE):
            return _deny(store, args.tenant_id, args.key_id,
                         audit_mod.ACTION_REVOKE)
        try:
            record = store.revoke(
                args.key_id, args.tenant_id, args.reason, args.operator
            )
        except LedgerError as exc:
            return _ledger_fail(exc)
        if record is None:
            if not _attempt(
                store, args.tenant_id, args.key_id,
                audit_mod.ACTION_REVOKE, audit_mod.OUTCOME_REJECTED,
            ):
                return 1
            return _fail("key not found", 4)
        _print(record.to_status_response())
        return 0

    if args.command == "status":
        if not is_valid_key_id(args.key_id):
            if not _identifiers_ok(args.tenant_id, args.key_id):
                if not _conflict(store):
                    return 1
            return _fail("field key_id must be a UUID4", 2)
        if not allowed(audit_mod.ACTION_READ):
            return _deny(store, args.tenant_id, args.key_id,
                         audit_mod.ACTION_READ)
        record = store.get(args.key_id, args.tenant_id)
        if record is None:
            if not _attempt(
                store, args.tenant_id, args.key_id,
                audit_mod.ACTION_READ, audit_mod.OUTCOME_REJECTED,
            ):
                return 1
            return _fail("key not found", 4)
        if not _attempt(
            store, args.tenant_id, args.key_id,
            audit_mod.ACTION_READ, audit_mod.OUTCOME_SUCCESS,
        ):
            return 1
        _print(record.to_status_response())
        return 0

    if args.command == "export":
        if not args.tenant_id or not args.passphrase:
            if not _identifiers_ok(args.tenant_id, args.key_id):
                if not _conflict(store):
                    return 1
            elif not _attempt(
                store, args.tenant_id, args.key_id,
                audit_mod.ACTION_EXPORT, audit_mod.OUTCOME_REJECTED,
            ):
                return 1
            return _fail(
                "field passphrase must be a non-empty string", 2
            )
        if not is_valid_key_id(args.key_id):
            if not _conflict(store):
                return 1
            return _fail("field key_id must be a UUID4", 2)
        if not allowed(audit_mod.ACTION_EXPORT):
            return _deny(store, args.tenant_id, args.key_id,
                         audit_mod.ACTION_EXPORT)
        try:
            bundle = store.export_bundle(
                args.key_id, args.tenant_id, args.passphrase
            )
        except LedgerError as exc:
            return _ledger_fail(exc)
        if bundle is None:
            if not _attempt(
                store, args.tenant_id, args.key_id,
                audit_mod.ACTION_EXPORT, audit_mod.OUTCOME_REJECTED,
            ):
                return 1
            return _fail("key not found", 4)
        if not _attempt(
            store, args.tenant_id, args.key_id,
            audit_mod.ACTION_EXPORT, audit_mod.OUTCOME_SUCCESS,
        ):
            return 1
        _print({"format": keybundle.FORMAT, "bundle": bundle})
        return 0

    if args.command == "import":
        # The Idempotency-Key is validated first: a malformed key exits 2
        # with no side effect.
        if _idem_key_error(args.idempotency_key):
            return 2
        body = {
            "tenant_id": args.tenant_id,
            "passphrase": args.passphrase,
            "bundle": args.bundle,
        }
        path = "/v1/keys/import"
        decoded = {}

        def validator():
            # Cheap request-field checks, before the binding lookup. A
            # refusal is a plain exit-2 error with no audit event and never
            # consumes the key (mirrors the HTTP endpoint).
            if not args.tenant_id:
                return (2, "field tenant_id must be a non-empty string")
            if not args.passphrase:
                return (2, "field passphrase must be a non-empty string")
            if not args.bundle:
                return (2, "field bundle must be a non-empty string")
            return None

        def decoder():
            # Side-effect-free decryption after the replay precheck but
            # before the key is bound: a wrong passphrase/tampered bundle
            # exits 2 without an audit event and without consuming the key.
            try:
                payload = keybundle.decode_bundle(
                    args.bundle, args.passphrase
                )
            except keybundle.BundleError as exc:
                return (2, str(exc))
            decoded.update(payload)
            return None

        def execute(operation):
            key_id = decoded["key_id"]
            # Kind/exact key_id durable before any business check.
            op_store.update_details(
                operation,
                {"kind": "import", "key_id": key_id},
            )
            if not policies.is_allowed(
                args.tenant_id, audit_mod.ACTION_IMPORT, args.operator
            ):
                return _terminal_rejection(
                    op_store, store, operation,
                    args.tenant_id, key_id,
                    audit_mod.ACTION_IMPORT, 403,
                    "action not permitted by policy",
                )

            def stage_success(committed_record):
                body = committed_record.to_create_response()
                body["operation_id"] = operation.operation_id
                op_store.stage_terminal(operation, 201, body)

            status, record = store.import_bundle(
                args.tenant_id, decoded,
                event_id=operation.operation_id,
                lock_timeout=operations_mod.LOCK_WAIT_SECONDS,
                pre_commit=stage_success,
            )
            if status == IMPORT_CONFLICT:
                if record.tenant_id == args.tenant_id:
                    return _terminal_rejection(
                        op_store, store, operation,
                        args.tenant_id, record.key_id,
                        audit_mod.ACTION_IMPORT, 409,
                        "key_id already exists for this tenant",
                    )
                return _terminal_rejection(
                    op_store, store, operation,
                    args.tenant_id, record.key_id,
                    audit_mod.ACTION_IMPORT, 404, "key not found",
                )
            return 201, record.to_create_response()

        return idempotent_run(
            op_store, store, path, args.tenant_id, args.operator, body,
            args.idempotency_key, validator, execute, decoder,
        )

    if args.command == "backup":
        if not args.tenant_id or not args.passphrase:
            if not _identifiers_ok(args.tenant_id, None):
                if not _conflict(store):
                    return 1
            elif not _attempt(
                store, args.tenant_id, None,
                audit_mod.ACTION_EXPORT, audit_mod.OUTCOME_REJECTED,
            ):
                return 1
            if not args.tenant_id:
                return _fail("field tenant_id must be a non-empty string", 2)
            return _fail(
                "field passphrase must be a non-empty string", 2
            )
        if not allowed(audit_mod.ACTION_EXPORT):
            return _deny(store, args.tenant_id, None,
                         audit_mod.ACTION_EXPORT)
        try:
            bundle = coordinator.backup_bundle(
                args.tenant_id, args.passphrase
            )
        except LedgerError as exc:
            return _ledger_fail(exc)
        if not _attempt(
            store, args.tenant_id, None,
            audit_mod.ACTION_EXPORT, audit_mod.OUTCOME_SUCCESS,
        ):
            return 1
        _print({"format": tenantbundle.FORMAT, "bundle": bundle})
        return 0

    if args.command == "restore":
        # The Idempotency-Key is validated first: a malformed key exits 2
        # with no side effect.
        if _idem_key_error(args.idempotency_key):
            return 2
        body = {
            "tenant_id": args.tenant_id,
            "passphrase": args.passphrase,
            "bundle": args.bundle,
        }
        path = "/v1/restore"
        decoded = {}

        def validator():
            # Cheap request-field checks, before the binding lookup; a
            # refusal is an exit-2 error with no audit event and never
            # consumes the key.
            if not args.tenant_id:
                return (2, "field tenant_id must be a non-empty string")
            if not args.passphrase:
                return (2, "field passphrase must be a non-empty string")
            if not args.bundle:
                return (2, "field bundle must be a non-empty string")
            return None

        def decoder():
            # Side-effect-free decryption after the replay precheck but
            # before the key is bound; failures exit 2 without an audit
            # event and without consuming the key.
            try:
                payload = tenantbundle.decode_bundle(
                    args.bundle, args.passphrase
                )
            except tenantbundle.TenantBundleError as exc:
                return (2, str(exc))
            decoded.update(payload)
            return None

        def execute(operation):
            key_ids = sorted(k["key_id"] for k in decoded["keys"])
            writes_policy = decoded["policy"] is not None
            # Kind/write-set durable before any business check; restore
            # events project key_id null via the rejection helper.
            op_store.update_details(
                operation,
                {
                    "kind": "restore",
                    "key_ids": key_ids,
                    "policy_restored": writes_policy,
                },
            )
            if not policies.is_allowed(
                args.tenant_id, audit_mod.ACTION_IMPORT, args.operator
            ):
                return _terminal_rejection(
                    op_store, store, operation,
                    args.tenant_id, None,
                    audit_mod.ACTION_IMPORT, 403,
                    "action not permitted by policy",
                )
            if decoded["tenant_id"] != args.tenant_id:
                return _terminal_rejection(
                    op_store, store, operation,
                    args.tenant_id, None,
                    audit_mod.ACTION_IMPORT, 404,
                    "tenant backup not found",
                )

            def stage_success():
                body = {
                    "tenant_id": args.tenant_id,
                    "key_ids": key_ids,
                    "policy_restored": writes_policy,
                    "operation_id": operation.operation_id,
                }
                op_store.stage_terminal(operation, 201, body)

            result = coordinator.restore(
                args.tenant_id, decoded,
                event_id=operation.operation_id,
                lock_timeout=operations_mod.LOCK_WAIT_SECONDS,
                pre_commit=stage_success,
            )
            if result.status == restore_mod.RESTORE_CREATED:
                return (
                    201,
                    {
                        "tenant_id": result.tenant_id,
                        "key_ids": result.key_ids,
                        "policy_restored": result.policy_restored,
                    },
                )
            if result.status == restore_mod.RESTORE_SAME_TENANT_CONFLICT:
                return _terminal_rejection(
                    op_store, store, operation,
                    args.tenant_id, None,
                    audit_mod.ACTION_IMPORT, 409,
                    "backup target already contains this data",
                )
            return _terminal_rejection(
                op_store, store, operation,
                args.tenant_id, None,
                audit_mod.ACTION_IMPORT, 404,
                "tenant backup not found",
            )

        return idempotent_run(
            op_store, store, path, args.tenant_id, args.operator, body,
            args.idempotency_key, validator, execute, decoder,
        )

    if args.command == "operation":
        if not args.tenant_id:
            return _fail("field tenant_id must be a non-empty string", 2)
        record = op_store.get(
            args.operation_id, args.tenant_id, args.operator
        )
        if record is None:
            # Unknown, malformed, another tenant's or another operator's
            # operation all look identical: never leak existence.
            return _fail("operation not found", 4)
        _print(record.to_status_response())
        return 0

    if args.command == "audit":
        if not args.tenant_id:
            return _fail("field tenant_id must be a non-empty string", 2)
        if args.key_id is not None and not is_valid_key_id(args.key_id):
            return _fail("field key_id must be a UUID4", 2)
        if args.action is not None and args.action not in audit_mod.ACTIONS:
            return _fail(
                "field action must be one of: %s"
                % ", ".join(audit_mod.ACTIONS),
                2,
            )
        if not 1 <= args.limit <= 1000:
            return _fail(
                "field limit must be an integer between 1 and 1000", 2
            )
        if not allowed(audit_mod.ACTION_AUDIT):
            if not _attempt(
                store, args.tenant_id, None,
                audit_mod.ACTION_AUDIT, audit_mod.OUTCOME_REJECTED,
            ):
                return 1
            return _fail("action not permitted by policy", 3)
        try:
            page = store.audit.query(
                args.tenant_id,
                key_id=args.key_id,
                action=args.action,
                limit=args.limit,
                cursor=args.cursor,
            )
        except InvalidCursor:
            return _fail("invalid or expired cursor", 2)
        except LedgerError as exc:
            return _ledger_fail(exc)
        _print(
            {
                "events": [e.to_response() for e in page.events],
                "next_cursor": page.next_cursor,
            }
        )
        return 0

    if args.command == "policy":
        return _policy_command(args, policies)

    return 2  # pragma: no cover - argparse enforces choices


def _policy_command(args, policies: PolicyStore) -> int:
    """Handle `policy show|set|delete`; management is exempt from policy."""
    tenant_id = args.tenant_id
    if not tenant_id:
        return _fail("field tenant_id must be a non-empty string", 2)

    if args.policy_command == "show":
        rules = policies.get(tenant_id)
        if rules is None:
            return _fail("policy not found", 4)
        try:
            policies.audit_read(tenant_id)
        except LedgerError as exc:
            return _ledger_fail(exc)
        _print(
            {"tenant_id": tenant_id,
             "rules": [r.to_json() for r in rules]}
        )
        return 0

    if args.policy_command == "set":
        try:
            raw = json.loads(args.rules)
        except ValueError:
            return _fail("field rules must be valid JSON", 2)
        try:
            rules = validate_rules(raw)
        except PolicyError as exc:
            return _fail(str(exc), 2)
        try:
            policies.put(tenant_id, rules)
        except LedgerError as exc:
            return _ledger_fail(exc)
        _print(
            {"tenant_id": tenant_id,
             "rules": [r.to_json() for r in rules]}
        )
        return 0

    # policy delete
    try:
        policies.delete(tenant_id)
    except LedgerError as exc:
        return _ledger_fail(exc)
    _print({"tenant_id": tenant_id, "deleted": True})
    return 0

"""KMS/HSM provider abstraction.

Every private key is owned by a *provider*: a local software key store by
default, or an external KMS/HSM reached through the ``module:factory`` entry
point named by ``KEYMGR_PROVIDER``. The rest of the package never touches raw
key material when a provider is in use: it only persists the opaque
``provider_id`` / ``handle`` / ``encrypted_material`` triple a provider
returns, and asks the provider to turn a handle back into exportable material.

Provider contract
-----------------
A provider instance exposes:

* ``provider_id``: a non-empty string;
* ``capabilities``: ``{"algorithms": ["AES256", "RSA2048"],
  "operations": ["generate", "rotate", "import_material",
  "export_material", "delete"]}``;
* ``generate(algorithm)`` / ``rotate(algorithm)`` ->
  ``{"handle", "public_key", "encrypted_material"}``;
* ``import_material(algorithm, public_key, material)`` -> the same triple;
* ``export_material(handle)`` -> ``{"public_key", "encrypted_material"}``;
* ``delete(handle)`` -> ``None``, idempotent.

The factory named by ``KEYMGR_PROVIDER=module:factory`` is imported lazily on
first use and called with no arguments. A missing module/factory, a factory
raising, or a returned object failing the contract all raise
:class:`ProviderUnavailable`; the service answers ``503`` (CLI exit ``1``) and
never falls back to the local provider.
"""

import base64
import importlib
import json
import os
import tempfile
import threading
import uuid
from typing import NamedTuple, Optional

from cryptography.exceptions import UnsupportedAlgorithm
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

from .crypto import SUPPORTED_ALGORITHMS, generate_key

#: Default provider id and the id of the built-in software provider.
LOCAL_PROVIDER_ID = "local"

OP_GENERATE = "generate"
OP_ROTATE = "rotate"
OP_IMPORT_MATERIAL = "import_material"
OP_EXPORT_MATERIAL = "export_material"
OP_DELETE = "delete"
OPERATIONS = (
    OP_GENERATE,
    OP_ROTATE,
    OP_IMPORT_MATERIAL,
    OP_EXPORT_MATERIAL,
    OP_DELETE,
)

_DEK_NAME = "local.dek"
_REGISTRY_NAME = "local-registry.json"
# Prefix for material wrapped by the local DEK; never reused for another
# encoding so wrapped blobs are self-describing on disk.
_WRAP_PREFIX = "pev1."
_NONCE_LEN = 12


class ProviderError(Exception):
    """Base class for provider failures."""


class ProviderUnavailable(ProviderError):
    """The provider cannot service the request (load/backend/handle failure).

    Surfaced as HTTP ``503`` / CLI exit code ``1``. The message is logged
    server-side; clients only ever see a generic status (handles and material
    never leave the boundary).
    """


class ProviderInvalidMaterial(ProviderError):
    """Material handed to the provider is malformed for the algorithm.

    Surfaced as HTTP ``400`` / CLI exit code ``2``; the message names the
    offending field but never embeds the material itself.
    """


class MaterialTriple(NamedTuple):
    """The provider-owned result of generate/rotate/import_material."""

    handle: str
    public_key: Optional[str]
    encrypted_material: str


class ExportedMaterial(NamedTuple):
    """Result of export_material: material plus its public component."""

    public_key: Optional[str]
    encrypted_material: str


def _b64e(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _b64d(text: str) -> bytes:
    return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))


def _require_triple(result, operation: str) -> MaterialTriple:
    """Validate a generate/rotate/import result has a handle and material."""
    if not isinstance(result, dict):
        raise ProviderUnavailable(
            "provider %s returned a non-object from %s"
            % ("external", operation)
        )
    handle = result.get("handle")
    material = result.get("encrypted_material")
    if not isinstance(handle, str) or not handle:
        raise ProviderUnavailable(
            "provider returned an empty handle from %s" % operation
        )
    if not isinstance(material, str) or not material:
        raise ProviderUnavailable(
            "provider returned empty encrypted_material from %s" % operation
        )
    public_key = result.get("public_key")
    if public_key is not None and not isinstance(public_key, str):
        raise ProviderUnavailable(
            "provider returned an invalid public_key from %s" % operation
        )
    return MaterialTriple(
        handle=handle, public_key=public_key, encrypted_material=material
    )


class KeyProvider:
    """Abstract provider; concrete providers implement the five operations."""

    provider_id = ""
    capabilities = {"algorithms": (), "operations": ()}

    def configure(self, data_dir: str) -> None:
        """Bind any persistent state to the data directory (optional)."""

    def generate(self, algorithm: str) -> MaterialTriple:
        raise NotImplementedError

    def rotate(self, algorithm: str) -> MaterialTriple:
        raise NotImplementedError

    def import_material(
        self,
        algorithm: str,
        public_key: Optional[str],
        material: str,
    ) -> MaterialTriple:
        raise NotImplementedError

    def export_material(self, handle: str) -> ExportedMaterial:
        raise NotImplementedError

    def delete(self, handle: str) -> None:
        raise NotImplementedError

    def supports(self, algorithm: str, operation: str) -> bool:
        caps = getattr(self, "capabilities", {}) or {}
        return (
            algorithm in caps.get("algorithms", ())
            and operation in caps.get("operations", ())
        )


def _validate_external(obj) -> None:
    """Check a factory-built object satisfies the provider contract."""
    provider_id = getattr(obj, "provider_id", None)
    if not isinstance(provider_id, str) or not provider_id:
        raise ProviderUnavailable(
            "provider factory returned an object without a non-empty provider_id"
        )
    caps = getattr(obj, "capabilities", None)
    if not isinstance(caps, dict):
        raise ProviderUnavailable(
            "provider %r has no capabilities mapping" % provider_id
        )
    algorithms = caps.get("algorithms")
    operations = caps.get("operations")
    if not isinstance(algorithms, (list, tuple)) or not isinstance(
        operations, (list, tuple)
    ):
        raise ProviderUnavailable(
            "provider %r capabilities must list algorithms and operations"
            % provider_id
        )
    missing = [a for a in SUPPORTED_ALGORITHMS if a not in algorithms]
    if missing:
        raise ProviderUnavailable(
            "provider %r lacks required algorithms: %s"
            % (provider_id, ", ".join(missing))
        )
    missing_ops = [op for op in OPERATIONS if op not in operations]
    if missing_ops:
        raise ProviderUnavailable(
            "provider %r lacks required operations: %s"
            % (provider_id, ", ".join(missing_ops))
        )
    for name in OPERATIONS:
        if not callable(getattr(obj, name, None)):
            raise ProviderUnavailable(
                "provider %r is missing a callable %s() operation"
                % (provider_id, name)
            )
    configure = getattr(obj, "configure", None)
    if configure is not None and not callable(configure):
        raise ProviderUnavailable(
            "provider %r has a non-callable configure attribute" % provider_id
        )


class _SafeProvider:
    """Adapter around an external provider enforcing the error contract.

    ProviderError subtypes pass through unchanged; any other exception the
    external module raises is normalized to ProviderUnavailable so a backend
    fault always surfaces as 503 and never as a 500 or a fallback.
    """

    def __init__(self, inner) -> None:
        self._inner = inner
        self.provider_id = inner.provider_id
        self.capabilities = inner.capabilities

    def configure(self, data_dir: str) -> None:
        try:
            configure = getattr(self._inner, "configure", None)
            if configure is not None:
                configure(data_dir)
        except ProviderError:
            raise
        except Exception as exc:
            raise ProviderUnavailable(
                "provider %r failed to initialize" % self.provider_id
            ) from exc

    def _call(self, name: str, *args):
        method = getattr(self._inner, name)
        try:
            return method(*args)
        except ProviderError:
            raise
        except Exception as exc:
            raise ProviderUnavailable(
                "provider %r operation %s failed" % (self.provider_id, name)
            ) from exc

    def generate(self, algorithm: str) -> MaterialTriple:
        return _require_triple(self._call("generate", algorithm), "generate")

    def rotate(self, algorithm: str) -> MaterialTriple:
        return _require_triple(self._call("rotate", algorithm), "rotate")

    def import_material(self, algorithm, public_key, material) -> MaterialTriple:
        return _require_triple(
            self._call("import_material", algorithm, public_key, material),
            "import_material",
        )

    def export_material(self, handle: str) -> ExportedMaterial:
        result = self._call("export_material", handle)
        if not isinstance(result, dict):
            raise ProviderUnavailable(
                "provider returned a non-object from export_material"
            )
        material = result.get("encrypted_material")
        if not isinstance(material, str) or not material:
            raise ProviderUnavailable(
                "provider returned empty encrypted_material from export_material"
            )
        public_key = result.get("public_key")
        if public_key is not None and not isinstance(public_key, str):
            raise ProviderUnavailable(
                "provider returned an invalid public_key from export_material"
            )
        return ExportedMaterial(
            public_key=public_key, encrypted_material=material
        )

    def delete(self, handle: str) -> None:
        # Idempotent by contract; even so, a backend fault on delete is a 503
        # (the caller may retry, and delete must remain idempotent).
        self._call("delete", handle)


class LocalProvider(KeyProvider):
    """Built-in software provider.

    Raw material never lands in a key file: each generated/imported key is
    wrapped with AES-256-GCM under a data-encryption key kept in
    ``local.dek`` (0600), and only the wrapped blob plus an opaque handle is
    persisted. A small registry (``local-registry.json``, 0600) maps each
    handle to its algorithm and wrapped blob, so ``export_material(handle)``
    can re-derive the raw material and ``delete`` stays idempotent. The
    registry stores only DEK-wrapped material, never plaintext.
    """

    provider_id = LOCAL_PROVIDER_ID
    capabilities = {
        "algorithms": tuple(SUPPORTED_ALGORITHMS),
        "operations": OPERATIONS,
    }

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._data_dir: Optional[str] = None
        self._dek: Optional[bytes] = None
        self._registry: dict = {}
        self._configured = False

    # -- state -------------------------------------------------------------
    def configure(self, data_dir: str) -> None:
        with self._lock:
            if self._configured and self._data_dir == data_dir:
                return
            os.makedirs(data_dir, exist_ok=True)
            self._data_dir = data_dir
            self._dek = self._load_or_create_dek(data_dir)
            self._registry = self._load_registry(data_dir)
            self._configured = True

    @staticmethod
    def _load_or_create_dek(data_dir: str) -> bytes:
        path = os.path.join(data_dir, _DEK_NAME)
        try:
            with open(path, "rb") as fh:
                dek = fh.read()
            if len(dek) == 32:
                return dek
        except FileNotFoundError:
            pass
        except OSError as exc:
            raise ProviderUnavailable("cannot read local DEK: %s" % exc) from exc
        dek = os.urandom(32)
        try:
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            try:
                os.write(fd, dek)
                os.fsync(fd)
            finally:
                os.close(fd)
        except FileExistsError:
            with open(path, "rb") as fh:
                dek = fh.read()
        except OSError as exc:
            raise ProviderUnavailable("cannot write local DEK: %s" % exc) from exc
        if len(dek) != 32:
            raise ProviderUnavailable("local DEK file is corrupt")
        return dek

    @staticmethod
    def _load_registry(data_dir: str) -> dict:
        path = os.path.join(data_dir, _REGISTRY_NAME)
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except FileNotFoundError:
            return {}
        except (OSError, ValueError) as exc:
            raise ProviderUnavailable(
                "cannot read local handle registry: %s" % exc
            ) from exc
        if not isinstance(data, dict):
            raise ProviderUnavailable("local handle registry is corrupt")
        return data

    def _persist_registry_locked(self) -> None:
        path = os.path.join(self._data_dir, _REGISTRY_NAME)
        fd, tmp_path = tempfile.mkstemp(dir=self._data_dir, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(self._registry, fh)
                fh.flush()
                os.fsync(fh.fileno())
            os.chmod(tmp_path, 0o600)
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def _require_configured(self) -> None:
        if not self._configured:
            raise ProviderUnavailable("local provider is not configured")

    # -- wrapping ----------------------------------------------------------
    def _wrap_locked(self, raw_material: str) -> str:
        nonce = os.urandom(_NONCE_LEN)
        ct = AESGCM(self._dek).encrypt(
            nonce, raw_material.encode("utf-8"), None
        )
        return _WRAP_PREFIX + _b64e(nonce) + "." + _b64e(ct)

    def _unwrap_locked(self, blob: str) -> str:
        if not isinstance(blob, str) or not blob.startswith(_WRAP_PREFIX):
            raise ProviderUnavailable("stored material is not a local blob")
        try:
            nonce_b, ct_b = blob[len(_WRAP_PREFIX):].split(".", 1)
            nonce = _b64d(nonce_b)
            ct = _b64d(ct_b)
            raw = AESGCM(self._dek).decrypt(nonce, ct, None)
            return raw.decode("utf-8")
        except Exception as exc:
            raise ProviderUnavailable(
                "cannot unwrap local material"
            ) from exc

    # -- material validation ----------------------------------------------
    @staticmethod
    def _validate_material(
        algorithm: str, public_key, material
    ):
        """Validate raw (legacy-shaped) material for an algorithm.

        AES material is base64 of exactly 32 bytes and has no public part;
        RSA material is a PEM private key of exactly 2048 bits, and the
        supplied public key (when present) must match it. Returns the parsed
        RSA private key (None for AES).
        """
        if not isinstance(material, str) or not material:
            raise ProviderInvalidMaterial(
                "field encrypted_material must be a non-empty string"
            )
        if algorithm == "AES256":
            if public_key is not None:
                raise ProviderInvalidMaterial(
                    "field public_key must be null for AES256"
                )
            try:
                raw = base64.b64decode(material, validate=True)
            except (ValueError, TypeError) as exc:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be valid base64 for AES256"
                ) from exc
            if len(raw) != 32:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must decode to 32 bytes for AES256"
                )
            return None
        if algorithm == "RSA2048":
            try:
                private_key = serialization.load_pem_private_key(
                    material.encode("utf-8"), password=None
                )
            except (ValueError, TypeError, UnsupportedAlgorithm) as exc:
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be a PEM private key for RSA2048"
                ) from exc
            if not isinstance(private_key, rsa.RSAPrivateKey) or (
                private_key.key_size != 2048
            ):
                raise ProviderInvalidMaterial(
                    "field encrypted_material must be a 2048-bit RSA private key"
                )
            if public_key is not None:
                if not isinstance(public_key, str) or not public_key:
                    raise ProviderInvalidMaterial(
                        "field public_key must be a PEM string for RSA2048"
                    )
                try:
                    supplied = serialization.load_pem_public_key(
                        public_key.encode("utf-8")
                    )
                    if not isinstance(supplied, rsa.RSAPublicKey):
                        raise ValueError("not an RSA public key")
                except (ValueError, TypeError, UnsupportedAlgorithm) as exc:
                    raise ProviderInvalidMaterial(
                        "field public_key must be a PEM RSA public key"
                    ) from exc
                expected = private_key.public_key().public_bytes(
                    encoding=serialization.Encoding.DER,
                    format=serialization.PublicFormat.SubjectPublicKeyInfo,
                )
                actual = supplied.public_bytes(
                    encoding=serialization.Encoding.DER,
                    format=serialization.PublicFormat.SubjectPublicKeyInfo,
                )
                if expected != actual:
                    raise ProviderInvalidMaterial(
                        "field public_key does not match the private key"
                    )
            return private_key
        raise ProviderInvalidMaterial(
            "unsupported value for field algorithm: %r (supported: %s)"
            % (algorithm, ", ".join(SUPPORTED_ALGORITHMS))
        )

    @staticmethod
    def _public_pem(private_key) -> str:
        return private_key.public_key().public_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PublicFormat.SubjectPublicKeyInfo,
        ).decode("ascii")

    def _adopt(
        self,
        algorithm: str,
        public_key,
        raw_material: str,
    ) -> MaterialTriple:
        """Validate raw material, wrap it under the DEK, mint a handle."""
        self._require_configured()
        private_key = self._validate_material(algorithm, public_key, raw_material)
        if algorithm == "RSA2048" and public_key is None:
            public_key = self._public_pem(private_key)
        handle = uuid.uuid4().hex
        with self._lock:
            wrapped = self._wrap_locked(raw_material)
            self._registry[handle] = {
                "algorithm": algorithm,
                "wrapped": wrapped,
            }
            self._persist_registry_locked()
        return MaterialTriple(
            handle=handle,
            public_key=public_key,
            encrypted_material=wrapped,
        )

    # -- KeyProvider operations -------------------------------------------
    def generate(self, algorithm: str) -> MaterialTriple:
        generated = generate_key(algorithm)
        return self._adopt(
            algorithm, generated.public_material, generated.private_material
        )

    def rotate(self, algorithm: str) -> MaterialTriple:
        # A rotated version is brand-new material owned by the same provider.
        return self.generate(algorithm)

    def import_material(
        self,
        algorithm: str,
        public_key,
        material: str,
    ) -> MaterialTriple:
        return self._adopt(algorithm, public_key, material)

    def export_material(self, handle: str) -> ExportedMaterial:
        """Return the raw bundle-shaped material for a registered handle.

        The registry keeps the DEK-wrapped blob, which is unwrapped here. The
        returned material is only ever sealed inside a passphrase-encrypted
        export bundle; an unknown handle is ProviderUnavailable.
        """
        self._require_configured()
        if not isinstance(handle, str) or not handle:
            raise ProviderUnavailable("export_material requires a handle")
        with self._lock:
            meta = self._registry.get(handle)
            if meta is None:
                raise ProviderUnavailable("unknown handle")
            algorithm = meta.get("algorithm")
            blob = meta.get("wrapped")
            try:
                raw = self._unwrap_locked(blob)
            except ProviderUnavailable:
                raise
        if algorithm == "AES256":
            return ExportedMaterial(public_key=None, encrypted_material=raw)
        try:
            private_key = serialization.load_pem_private_key(
                raw.encode("utf-8"), password=None
            )
        except (ValueError, TypeError, UnsupportedAlgorithm) as exc:
            raise ProviderUnavailable("stored local material is corrupt") from exc
        return ExportedMaterial(
            public_key=self._public_pem(private_key),
            encrypted_material=raw,
        )

    def delete(self, handle: str) -> None:
        """Drop a handle from the registry. Idempotent and never fails 404."""
        self._require_configured()
        with self._lock:
            if handle in self._registry:
                del self._registry[handle]
                self._persist_registry_locked()


# -- module:factory loading -------------------------------------------------
_provider_lock = threading.Lock()
_provider: Optional[KeyProvider] = None
_configured_dir: Optional[str] = None
_LOCAL_SINGLETON = LocalProvider()


def _spec() -> str:
    return os.environ.get("KEYMGR_PROVIDER", "") or LOCAL_PROVIDER_ID


def active_is_local() -> bool:
    """Whether the configured active provider is the built-in local one.

    Reads the ``KEYMGR_PROVIDER`` spec without importing anything: the local
    provider is active only for an empty value or an explicit ``local``. This
    is used for the provider-selection gates (legacy-record adoption, legacy
    bundle import) that must never trigger an import of a module:factory
    provider from a plain read.
    """
    return _spec() == LOCAL_PROVIDER_ID


def _load_external(spec: str):
    module_name, sep, factory_name = spec.partition(":")
    if not sep or not module_name or not factory_name:
        raise ProviderUnavailable(
            "KEYMGR_PROVIDER must be 'local' or 'module:factory', got %r" % spec
        )
    try:
        module = importlib.import_module(module_name)
    except Exception as exc:
        raise ProviderUnavailable(
            "cannot import provider module %r: %s" % (module_name, exc)
        ) from exc
    target = module
    for part in factory_name.split("."):
        try:
            target = getattr(target, part)
        except AttributeError as exc:
            raise ProviderUnavailable(
                "provider module %r has no factory %r"
                % (module_name, factory_name)
            ) from exc
    if not callable(target):
        raise ProviderUnavailable(
            "provider factory %r is not callable" % factory_name
        )
    try:
        obj = target()
    except Exception as exc:
        raise ProviderUnavailable(
            "provider factory %r failed: %s" % (factory_name, exc)
        ) from exc
    _validate_external(obj)
    return _SafeProvider(obj)


def get_provider():
    """Return the configured provider, importing it lazily on first use.

    Raises ProviderUnavailable (never falls back) when the configured
    provider cannot be loaded or fails the contract.
    """
    global _provider
    if _provider is not None:
        return _provider
    with _provider_lock:
        if _provider is not None:
            return _provider
        spec = _spec()
        if spec == LOCAL_PROVIDER_ID:
            provider = _LOCAL_SINGLETON
        else:
            provider = _load_external(spec)
        if _configured_dir is not None:
            provider.configure(_configured_dir)
        _provider = provider
        return _provider


def configure(data_dir: str) -> KeyProvider:
    """Bind the data directory and load the provider.

    Records ``data_dir`` and configures the built-in local provider (needed
    to adopt pre-provider records), then returns the active provider —
    importing an external ``module:factory`` provider here if it has not been
    loaded yet.
    """
    global _configured_dir
    _configured_dir = data_dir
    _LOCAL_SINGLETON.configure(data_dir)
    provider = get_provider()
    provider.configure(data_dir)
    return provider


def configure_local(data_dir: str) -> "LocalProvider":
    """Bind state without importing an external provider.

    Used when the local provider is actually needed (local generation, lazy
    legacy adoption, local bundle import, startup cleanup of local handles):
    legacy records are owned by the local provider, never by whatever is
    configured now. The external factory stays unloaded until its first
    operation (lazy load).
    """
    global _configured_dir
    _configured_dir = data_dir
    _LOCAL_SINGLETON.configure(data_dir)
    return _LOCAL_SINGLETON


def bind_data_dir(data_dir: str) -> None:
    """Remember the data directory without loading any provider.

    Called at store open so the provider chosen lazily by
    :func:`get_provider` gets configured on first use, while startup itself
    neither imports a module:factory provider nor creates local provider
    state. Plain reads therefore load no provider.
    """
    global _configured_dir
    _configured_dir = data_dir


def get_local_provider() -> "LocalProvider":
    """Return the built-in local provider singleton, configured if a data
    directory has been bound (configure_local/bind_data_dir). Never imports a
    configured external provider."""
    if _configured_dir is not None and not _LOCAL_SINGLETON._configured:
        _LOCAL_SINGLETON.configure(_configured_dir)
    return _LOCAL_SINGLETON


def reset_for_tests() -> None:
    """Forget the cached provider (tests only)."""
    global _provider, _configured_dir
    with _provider_lock:
        _provider = None
        _configured_dir = None
        _LOCAL_SINGLETON._configured = False

"""Per-tenant action policies: validation, persistence and enforcement.

A policy document is a list of rules; each rule binds a ``subject`` (the
X-Operator-Id of the caller), a set of ``actions`` and an ``effect`` of
``allow`` or ``deny``. Enforcement, for one (tenant, subject, action):

* a tenant with no document is unrestricted (every action is allowed);
* among the rules whose subject equals the caller and whose actions contain
  the action, any ``deny`` wins over ``allow``;
* if no matching rule exists the action is denied (default deny).

Documents are stored as one JSON file per tenant, written through the same
outbox transaction as key records: the file first lands carrying the audit
event, the ledger append follows, then the marker is cleared; a crash in
between is repaired idempotently on the next open.
"""

import hashlib
import json
import os
import tempfile
import threading
from contextlib import contextmanager
from dataclasses import dataclass
from typing import Iterator, List, Optional

from . import audit as audit_mod
from .audit import AuditEvent, AuditLog, LedgerError

try:  # fcntl is POSIX-only; policy writes still work without it.
    import fcntl
except ImportError:  # pragma: no cover - non-POSIX platforms
    fcntl = None

# Actions a policy rule can govern. These are the same action names the audit
# ledger uses (the management actions policy_* are deliberately not governable).
POLICY_ACTIONS = (
    "create",
    "read",
    "rotate",
    "revoke",
    "import",
    "export",
    "audit",
)
EFFECTS = ("allow", "deny")
_POLICY_DIR = "policies"


class PolicyError(ValueError):
    """A policy document or rule failed validation (surfaced as 400)."""


@dataclass(frozen=True)
class Rule:
    """One policy rule: an effect on a set of actions for one subject."""

    subject: str
    actions: List[str]
    effect: str

    def to_json(self) -> dict:
        """Serialize to a plain dict; actions are emitted sorted."""
        return {
            "subject": self.subject,
            "actions": list(self.actions),
            "effect": self.effect,
        }

    @classmethod
    def from_json(cls, data: dict) -> "Rule":
        # Documents on disk were validated when written, but validate again
        # on the way in so a hand-edited file can never break enforcement.
        return validate_rule(data)

    def signature(self):
        """Dedup key: same subject/effect with the same unordered action set."""
        return self.subject, self.effect, frozenset(self.actions)


def validate_rule(raw, index: Optional[int] = None) -> Rule:
    """Validate one rule object; raise PolicyError naming the bad field.

    ``index`` prefixes field names with ``rules[i].`` when the rule comes from
    a document; a standalone rule names the bare fields.
    """
    where = "rules[%d]." % index if index is not None else ""

    def err(message: str) -> PolicyError:
        return PolicyError(message)

    if not isinstance(raw, dict):
        raise err("field %s must be an object" % (where.rstrip(".") if index is not None else "rule"))
    known = {"subject", "actions", "effect"}
    unknown = set(raw) - known
    if unknown:
        raise err(
            "unknown field %s%s"
            % (where, sorted(unknown)[0])
        )
    subject = raw.get("subject")
    if not isinstance(subject, str) or not subject:
        raise err("field %ssubject must be a non-empty string" % where)
    effect = raw.get("effect")
    if not isinstance(effect, str) or effect not in EFFECTS:
        raise err(
            "field %seffect must be one of: %s"
            % (where, ", ".join(EFFECTS))
        )
    actions = raw.get("actions")
    if not isinstance(actions, list) or not actions:
        raise err(
            "field %sactions must be a non-empty array" % where
        )
    clean_actions = []
    for action in actions:
        if not isinstance(action, str) or not action:
            raise err(
                "field %sactions must be non-empty strings" % where
            )
        if action not in POLICY_ACTIONS:
            raise err(
                "field %sactions has unknown action %r (allowed: %s)"
                % (where, action, ", ".join(POLICY_ACTIONS))
            )
        if action not in clean_actions:
            # Duplicates within one rule are dropped, not an error: the action
            # set is unordered, so ["read", "read"] carries no extra meaning.
            clean_actions.append(action)
    return Rule(subject=subject, actions=clean_actions, effect=effect)


def validate_rules(raw) -> List[Rule]:
    """Validate a full rules array; [] is valid and means default-deny."""
    if not isinstance(raw, list):
        raise PolicyError("field rules must be an array")
    rules: List[Rule] = []
    seen = set()
    for index, item in enumerate(raw):
        rule = validate_rule(item, index)
        if rule.signature() in seen:
            raise PolicyError(
                "field rules contains a duplicate rule at index %d "
                "(same subject, effect and unordered actions)" % index
            )
        seen.add(rule.signature())
        rules.append(rule)
    return rules


class PolicyStore:
    """File-backed per-tenant policy documents."""

    def __init__(self, data_dir: str, audit_log: Optional[AuditLog] = None) -> None:
        self.data_dir = data_dir
        self.dir_path = os.path.join(data_dir, _POLICY_DIR)
        os.makedirs(self.dir_path, exist_ok=True)
        self.audit = audit_log if audit_log is not None else AuditLog(data_dir)
        self._write_lock = threading.Lock()
        self._recover_pending_events()

    # -- on-disk shape -----------------------------------------------------
    def path_for(self, tenant_id: str) -> str:
        """Public accessor for a tenant's policy document path."""
        return self._path_for(tenant_id)

    def _path_for(self, tenant_id: str) -> str:
        # Tenant ids are free-form strings, so never use them as a filename:
        # key the file by a digest of the tenant instead.
        digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
        return os.path.join(self.dir_path, digest + ".json")

    def _lock_path_for(self, tenant_id: str) -> str:
        digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
        return os.path.join(self.dir_path, digest + ".lock")

    @contextmanager
    def tenant_lock(
        self, tenant_id: str, timeout: Optional[float] = None
    ) -> Iterator[None]:
        """Serialize all writes to one tenant's policy across processes.

        Pairs the in-process write lock with an exclusive ``fcntl`` lock on a
        per-tenant sidecar file, so a put/delete/restore/backup in another
        process cannot interleave with this one's read-modify-write. With a
        finite ``timeout`` (idempotent restore) the wait is bounded and raises
        :class:`~keymgr.store.LockTimeout` when it elapses.
        """
        import time as _time

        from .store import LockTimeout

        deadline = None if timeout is None else _time.monotonic() + timeout
        if timeout is None:
            self._write_lock.acquire()
        else:
            if not self._write_lock.acquire(timeout=max(timeout, 0.0)):
                raise LockTimeout("policy:" + tenant_id)
        if fcntl is None:  # pragma: no cover - non-POSIX platforms
            try:
                yield
            finally:
                self._write_lock.release()
            return
        fd = os.open(
            self._lock_path_for(tenant_id), os.O_RDWR | os.O_CREAT, 0o600
        )
        acquired = False
        try:
            if deadline is None:
                fcntl.flock(fd, fcntl.LOCK_EX)
            else:
                while True:
                    try:
                        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                        break
                    except BlockingIOError:
                        remaining = deadline - _time.monotonic()
                        if remaining <= 0:
                            raise LockTimeout("policy:" + tenant_id)
                        _time.sleep(min(0.02, remaining))
            acquired = True
            yield
        finally:
            if acquired:
                fcntl.flock(fd, fcntl.LOCK_UN)
            os.close(fd)
            self._write_lock.release()

    def _write_atomic(self, path: str, payload: dict) -> None:
        fd, tmp_path = tempfile.mkstemp(dir=self.dir_path, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(payload, fh)
                fh.flush()
                os.fsync(fh.fileno())
            os.chmod(tmp_path, 0o600)
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def _read_doc(self, path: str):
        """Return (tenant_id, rules, pending_event), or None if unreadable."""
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except (OSError, ValueError):
            return None
        try:
            rules = [Rule.from_json(r) for r in data["rules"]]
            return data["tenant_id"], rules, data.get("pending_event")
        except (KeyError, TypeError, ValueError, PolicyError):
            return None

    def _recover_pending_events(self) -> None:
        """Commit outbox events left pending by a crashed process."""
        try:
            names = os.listdir(self.dir_path)
        except OSError:
            return
        for name in names:
            if not name.endswith(".json") and not name.endswith(".json.del"):
                continue
            path = os.path.join(self.dir_path, name)
            doc = self._read_doc(path)
            if doc is None:
                continue
            tenant_id, rules, pending_event = doc
            if not pending_event:
                # A tombstone left behind after a successful ledger append:
                # finish the delete.
                if name.endswith(".del"):
                    try:
                        os.unlink(path)
                    except OSError:
                        pass
                continue
            # A multi-file tenant restore transaction is resolved by the
            # RestoreCoordinator (its manifest drives the shared event).
            if isinstance(pending_event, dict) and pending_event.get("_restore"):
                continue
            event = AuditEvent.from_json(pending_event)
            if name.endswith(".json.del"):                # A delete tombstone. If the original file is still on disk the
                # crash happened before the unlink, so the delete never
                # happened: discard the tombstone without appending. Otherwise
                # finish the transaction (append is idempotent on event_id).
                original = path[: -len(".del")]
                if os.path.exists(original):
                    try:
                        os.unlink(path)
                    except OSError:
                        pass
                    continue
                self.audit.append(event)
                try:
                    os.unlink(path)
                except OSError:
                    pass
            else:
                # append() is idempotent on event_id.
                self.audit.append(event)
                self._write_atomic(
                    path,
                    {"tenant_id": tenant_id,
                     "rules": [r.to_json() for r in rules],
                     "pending_event": None},
                )

    def _commit_put(self, tenant_id: str, rules: List[Rule],
                    event: AuditEvent, existed: bool, previous: Optional[dict]):
        """Write a document and its event as one logical transaction."""
        path = self._path_for(tenant_id)
        doc = {
            "tenant_id": tenant_id,
            "rules": [r.to_json() for r in rules],
            "pending_event": event.to_json(),
        }
        self._write_atomic(path, doc)
        try:
            self.audit.append(event)
        except BaseException:
            if not existed:
                try:
                    os.unlink(path)
                except OSError:
                    pass
            elif previous is not None:
                self._write_atomic(path, previous)
            raise
        # The durable ledger append is the commit point; clearing the marker
        # is post-commit housekeeping. A failure here leaves the marker for
        # startup recovery and must never roll the document back or fail the
        # request.
        doc["pending_event"] = None
        try:
            self._write_atomic(path, doc)
        except OSError:
            pass

    # -- public API --------------------------------------------------------
    def get(self, tenant_id: str) -> Optional[List[Rule]]:
        """Return the tenant's rules, or None when no document exists."""
        doc = self._read_doc(self._path_for(tenant_id))
        if doc is None:
            return None
        return doc[1]

    def put(self, tenant_id: str, rules: List[Rule]) -> List[Rule]:
        """Replace (or create) the tenant's document and audit policy_update."""
        with self.tenant_lock(tenant_id):
            path = self._path_for(tenant_id)
            existed = os.path.exists(path)
            previous = None
            if existed:
                try:
                    with open(path, "r", encoding="utf-8") as fh:
                        previous = json.load(fh)
                except (OSError, ValueError) as exc:
                    raise LedgerError(
                        "cannot read policy document: %s" % exc
                    ) from exc
            event = self.audit.new_event(
                tenant_id, audit_mod.ACTION_POLICY_UPDATE, None,
                audit_mod.OUTCOME_SUCCESS,
            )
            self._commit_put(tenant_id, rules, event, existed, previous)
        return rules

    def delete(self, tenant_id: str) -> None:
        """Delete the tenant's document and audit policy_delete.

        Tombstone sequence: write a ``.json.del`` marker carrying the event,
        unlink the document, append the event, then remove the marker. A crash
        between any two steps is repaired on the next open. If the ledger
        append itself fails, the original document is restored byte-for-byte
        and the tombstone discarded, so a failed delete never takes effect.
        Deleting a tenant that has no document still records the event.
        """
        with self.tenant_lock(tenant_id):
            path = self._path_for(tenant_id)
            existed = os.path.exists(path)
            event = self.audit.new_event(
                tenant_id, audit_mod.ACTION_POLICY_DELETE, None,
                audit_mod.OUTCOME_SUCCESS,
            )
            if not existed:
                self.audit.append(event)
                return
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    previous = json.load(fh)
            except (OSError, ValueError) as exc:
                raise LedgerError(
                    "cannot read policy document: %s" % exc
                ) from exc
            tombstone = path + ".del"
            self._write_atomic(
                tombstone,
                {"tenant_id": tenant_id, "rules": [],
                 "pending_event": event.to_json()},
            )
            os.unlink(path)
            try:
                # From here on a crash is repaired from the tombstone; the
                # append is idempotent on event_id.
                self.audit.append(event)
            except BaseException:
                # The ledger write failed: roll the delete back so the
                # document and its event never diverge.
                self._write_atomic(path, previous)
                try:
                    os.unlink(tombstone)
                except OSError:
                    pass
                raise
            try:
                os.unlink(tombstone)
            except OSError:
                pass

    def audit_read(self, tenant_id: str) -> None:
        """Record a successful policy_read (the document is never modified)."""
        event = self.audit.new_event(
            tenant_id, audit_mod.ACTION_POLICY_READ, None,
            audit_mod.OUTCOME_SUCCESS,
        )
        self.audit.append(event)

    def is_allowed(self, tenant_id: str, action: str, subject: str) -> bool:
        """Enforce the tenant document for (subject, action).

        No document means unrestricted. Otherwise deny wins, and an action no
        rule matches is denied.
        """
        rules = self.get(tenant_id)
        if rules is None:
            return True
        allowed = False
        for rule in rules:
            if rule.subject != subject or action not in rule.actions:
                continue
            if rule.effect == "deny":
                return False
            allowed = True
        return allowed

    # -- tenant restore hooks ---------------------------------------------
    def owner_of_path(self, path: str) -> Optional[str]:
        """Return the owning tenant_id recorded inside a policy file."""
        doc = self._read_doc(path)
        if doc is None:
            return None
        return doc[0]

    def write_restore_pending(
        self, tenant_id: str, rules: List[Rule], marker: dict
    ) -> None:
        """Atomically write a restored policy document carrying the marker.

        Used by the RestoreCoordinator; the caller guarantees no document
        exists for the tenant and holds the write lock.
        """
        self._write_atomic(
            self._path_for(tenant_id),
            {
                "tenant_id": tenant_id,
                "rules": [r.to_json() for r in rules],
                "pending_event": marker,
            },
        )

    def clear_restore_pending(self, tenant_id: str, rules: List[Rule]) -> None:
        """Rewrite a restored policy document without its pending marker."""
        self._write_atomic(
            self._path_for(tenant_id),
            {
                "tenant_id": tenant_id,
                "rules": [r.to_json() for r in rules],
                "pending_event": None,
            },
        )

    def remove_restore_file(self, tenant_id: str) -> None:
        """Delete a policy document written by a restore being rolled back."""
        try:
            os.unlink(self._path_for(tenant_id))
        except FileNotFoundError:
            pass

"""Cryptographic key generation for supported algorithms."""

import base64
import os
from typing import NamedTuple, Optional

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa

SUPPORTED_ALGORITHMS = ("AES256", "RSA2048")


class GeneratedKey(NamedTuple):
    """Result of generating a key.

    public_material is PEM (SubjectPublicKeyInfo) for RSA, None for AES.
    private_material stays server-side only (PEM for RSA, base64 for AES).
    """

    public_material: Optional[str]
    private_material: str


def _generate_aes256() -> GeneratedKey:
    """Generate a 256-bit AES key (no public component)."""
    raw = os.urandom(32)
    return GeneratedKey(
        public_material=None,
        private_material=base64.b64encode(raw).decode("ascii"),
    )


def _generate_rsa2048() -> GeneratedKey:
    """Generate a 2048-bit RSA key pair."""
    private_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    private_pem = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption(),
    ).decode("ascii")
    public_pem = private_key.public_key().public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo,
    ).decode("ascii")
    return GeneratedKey(
        public_material=public_pem,
        private_material=private_pem,
    )


def generate_key(algorithm: str) -> GeneratedKey:
    """Generate a new key for the given algorithm name."""
    if algorithm == "AES256":
        return _generate_aes256()
    if algorithm == "RSA2048":
        return _generate_rsa2048()
    raise ValueError("unsupported algorithm: %r" % (algorithm,))

